layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); border-left: 3px solid rgb(85, 85, 85); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: rgb(53, 61, 73); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.3s }
[data-ryt="hero"] h1 { color: rgb(0, 0, 0); font-family: var(--ryt-font-heading); font-size: 48px; font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(0, 0, 0); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: color-mix(in srgb, var(--ryt-bg) 70%, transparent) 0px 0px 5px, color-mix(in srgb, var(--ryt-bg) 70%, transparent) 0px 0px 10px, color-mix(in srgb, var(--ryt-bg) 70%, transparent) 0px 0px 20px, color-mix(in srgb, var(--ryt-bg) 70%, transparent) 0px 0px 40px, color-mix(in srgb, var(--ryt-bg) 70%, transparent) 0px 0px 80px, color-mix(in srgb, var(--ryt-bg) 70%, transparent) 0px 0px 90px, color-mix(in srgb, var(--ryt-bg) 70%, transparent) 0px 0px 100px, color-mix(in srgb, var(--ryt-bg) 70%, transparent) 0px 0px 150px; transition: all }
[data-ryt="section"] > h2 { color: rgb(53, 61, 73); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(53, 61, 73); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="button"] { color: var(--ryt-bg); background-color: var(--ryt-accent); border-radius: 4px; box-shadow: rgba(0, 0, 0, 0.1) 0px 4px 6px 0px; font-family: Arial; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 16px; padding-bottom: 8px; padding-left: 16px; transition: background-color 0.3s }
[data-ryt="brand"] { color: rgb(53, 61, 73); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 40px; font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(53, 61, 73); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: color 0.3s }
[data-ryt="review"] { color: rgb(53, 61, 73); font-family: var(--ryt-font-heading); font-size: 14.4px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(53, 61, 73); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: rgb(53, 61, 73); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(53, 61, 73); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.3s }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(53, 61, 73); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 24px; font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(53, 61, 73); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #353d49 }
[data-ryt="nav"] a:hover { color: #353d49 }
[data-ryt="button"]:hover { background-color: #fff; background-color: #879094 }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #353d49 }
